// --- FIGHTING SOUND EFFECTS ---
const sfx_jab = new Audio('data:audio/wav;base64,');
const sfx_uppercut = new Audio('data:audio/wav;base64,');
const sfx_kick = new Audio('data:audio/wav;base64,');
const sfx_comboAttack = new Audio('data:audio/wav;base64,');
const sfx_assistShoot = new Audio('data:audio/wav;base64,');
const sfx_shadePunch = new Audio('data:audio/wav;base64,');
const sfx_shadeKick = new Audio('data:audio/wav;base64,');
const sfx_serpent = new Audio('data:audio/wav;base64,');
const sfx_sticker = new Audio('data:audio/wav;base64,');

const SFX_VOLUME = 0.5;
[sfx_jab, sfx_uppercut, sfx_kick, sfx_comboAttack, sfx_assistShoot, sfx_shadePunch, sfx_shadeKick, sfx_serpent, sfx_sticker].forEach(s => s.volume = SFX_VOLUME);

function playSfx(sound) {
  sound.currentTime = 0;
  sound.play().catch(() => {});
}
